arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' --data '{"query":"{ a: __type(name: \"Mutation\") { fields { name args { name type { kind name ofType { kind name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['a']['fields']:
    if 'ycle' in f['name']:
        print(f['name'])
        for a in f['args']:
            t=a['type']; tn = t['name'] or (t['ofType']['name'] if t['ofType'] else str(t['kind']))
            print('   ', a['name'], '->', tn)
"

